// Builds the paper pages from data/papers.json:
//   src/content/docs/resources/papers.md         the table, filterable and sortable
//   src/content/docs/resources/reading-queue.md  papers not yet read, most cited first
//   src/content/docs/resources/timeline.md       papers per year and type
//   public/papers.bib                            BibTeX export
//
//   node scripts/papers.mjs           render from the stored counts
//   node scripts/papers.mjs --update  first refresh the counts from OpenAlex (needs network)
//   node scripts/papers.mjs --check   fail if the generated files differ from the data
//
// Papers with a DOI or arXiv id are looked up by it; others by title and year. A paper that
// cannot be matched keeps its old count (or none). Add a paper by appending to data/papers.json.
import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);
const dataFile = new URL('data/papers.json', root);
const papers = JSON.parse(readFileSync(dataFile, 'utf8'));

const API = 'https://api.openalex.org/works';
const fields = 'select=id,title,publication_year,cited_by_count';

async function lookup(p) {
	let url;
	if (p.doi) url = `${API}/doi:${p.doi}?${fields}`;
	else if (p.arxiv) url = `${API}/doi:10.48550/arXiv.${p.arxiv}?${fields}`;
	else if (p.title)
		url = `${API}?filter=title.search:${encodeURIComponent(p.title.replace(/[,|:]/g, ' '))},publication_year:${p.year}&per-page=1&${fields}`;
	else return null;
	const res = await fetch(url);
	if (!res.ok) return null;
	const body = await res.json();
	return body.results ? (body.results[0] ?? null) : body;
}

if (process.argv.includes('--update')) {
	const today = new Date().toISOString().slice(0, 10);
	for (const p of papers) {
		try {
			const work = await lookup(p);
			if (work) {
				p.citations = work.cited_by_count;
				p.citationsDate = today;
			} else console.warn(`no match: ${p.ref}`);
		} catch (err) {
			console.warn(`failed: ${p.ref}: ${err.message}`);
		}
	}
	writeFileSync(dataFile, JSON.stringify(papers, null, 2) + '\n');
}

const types = {
	review: 'Survey of a field.',
	experiment: 'Measurements of spokes or of a discharge.',
	simulation: 'PIC, fluid or other spatially resolved numerical model.',
	theory: 'Analytic or phenomenological model.',
	model: 'Global or ionization region model (0D, volume averaged).',
	unclassified: 'Known only from a reference list; type to be checked.',
};
const typeOrder = Object.keys(types);

const dates = papers.map((p) => p.citationsDate).filter(Boolean).sort();
const asOf = dates.length ? `Counts from OpenAlex, as of ${dates.at(-1)}.` : 'Counts not yet filled in.';
const esc = (s) => s.replace(/\|/g, '\\|');

const links = (p) => {
	const out = [];
	if (p.summary) out.push(`[summary](${p.summary})`);
	if (p.arxiv) out.push(`[arXiv](https://arxiv.org/abs/${p.arxiv})`);
	if (p.doi) out.push(`[DOI](https://doi.org/${p.doi})`);
	return out.length ? ` (${out.join(', ')})` : '';
};
const cell = (p) => esc(p.title ? `${p.ref}, *${p.title}*` : p.ref) + links(p);
const bearsOn = (p) => {
	const q = p.questions?.length === 8 ? ['all questions'] : (p.questions ?? []);
	const r = p.rung ? [`rung ${p.rung}`] : [];
	return [...q, ...r].join(', ') || '–';
};
const cites = (p) => p.citations ?? '–';
const header = (title, description, order) =>
	`---\ntitle: ${title}\ndescription: ${description}\nsidebar:\n  order: ${order}\n---\n\n<!-- Generated by scripts/papers.mjs from data/papers.json. Edit the data file, not this page. -->\n\n`;

// Papers page
const byType = [...papers].sort(
	(a, b) => typeOrder.indexOf(a.type) - typeOrder.indexOf(b.type) || b.year - a.year,
);
const opts = (values) => values.map((v) => `<option value="${v}">${v}</option>`).join('');
const papersPage =
	header(
		'Paper overview',
		'Every relevant paper in one table, with its type, how it is known and its citation count.',
		2,
	) +
	`All papers these notes use. ${asOf} A dash means no count yet. **Status** is the mark described
in [About these notes](/about/). **Bears on** names the [open questions](/questions/) and
[model rungs](/simulations/model-ladder/) a paper is used for; papers without an entry there are
not yet tagged. The same papers grouped by topic are in the
[bibliography](/resources/bibliography/); the ones to read next are in the
[reading queue](/resources/reading-queue/), and [papers.bib](/papers.bib) has them as BibTeX.

| Type | Meaning |
|---|---|
${typeOrder.map((t) => `| **${t}** | ${types[t]} |`).join('\n')}

<div id="paper-filters" hidden>
<label>Type <select data-filter="type"><option value="">all</option>${opts(typeOrder)}</select></label>
<label>Status <select data-filter="status"><option value="">all</option>${opts(['read', 'abstract', 'cited'])}</select></label>
<label>Search <input type="search" data-filter="text" placeholder="author, title, year"></label>
<span>Click a column heading to sort.</span>
</div>

<div id="paper-table">

| Paper | Year | Type | Status | Bears on | Citations |
|---|---|---|---|---|---|
${byType
	.map(
		(p) =>
			`| ${cell(p)} | ${p.year} | ${p.type}${p.note ? ` (${p.note})` : ''} | ${p.status} | ${bearsOn(p)} | ${cites(p)} |`,
	)
	.join('\n')}

</div>

<style>
#paper-filters { display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; align-items: center; margin-block: 1rem; }
#paper-table th[data-sort] { cursor: pointer; }
#paper-table th[data-sort]::after { content: ' ↕'; opacity: 0.4; }
</style>

<script>
(() => {
	const box = document.getElementById('paper-filters');
	const table = document.querySelector('#paper-table table');
	if (!box || !table) return;
	box.hidden = false;
	const body = table.tBodies[0];
	const rows = [...body.rows];
	const col = { type: 2, status: 3 };
	const apply = () => {
		const v = Object.fromEntries([...box.querySelectorAll('[data-filter]')].map((e) => [e.dataset.filter, e.value.trim().toLowerCase()]));
		for (const r of rows) {
			const c = [...r.cells].map((x) => x.textContent.toLowerCase());
			r.hidden =
				(v.type && !c[col.type].startsWith(v.type)) ||
				(v.status && c[col.status] !== v.status) ||
				(v.text && !c.join(' ').includes(v.text));
		}
	};
	box.addEventListener('input', apply);
	const num = (s) => (/^\\d+$/.test(s) ? Number(s) : -1);
	[...table.tHead.rows[0].cells].forEach((th, i) => {
		th.dataset.sort = '';
		let dir = 1;
		th.addEventListener('click', () => {
			const numeric = i === 1 || i === 5;
			rows.sort((a, b) => {
				const x = a.cells[i].textContent.trim();
				const y = b.cells[i].textContent.trim();
				return dir * (numeric ? num(x) - num(y) : x.localeCompare(y));
			});
			dir = -dir;
			rows.forEach((r) => body.append(r));
		});
	});
})();
</script>
`;

// Reading queue
const queue = papers
	.filter((p) => p.status !== 'read')
	.sort(
		(a, b) =>
			(b.citations ?? -1) - (a.citations ?? -1) ||
			(b.questions?.length ?? 0) + (b.rung ? 1 : 0) - ((a.questions?.length ?? 0) + (a.rung ? 1 : 0)) ||
			b.year - a.year,
	);
const queuePage =
	header(
		'Reading queue',
		'Papers known only from an abstract or a reference list, most cited first.',
		3,
	) +
	`Papers marked **abstract** or **cited** in the [paper overview](/resources/papers/), most cited first.
Where counts are missing, papers already tagged with an open question or model rung come first, then
newer ones. ${asOf} Once a paper has been read, set its status to \`read\` in \`data/papers.json\`
and add a [summary](/summaries/).

| # | Paper | Status | Bears on | Citations |
|---|---|---|---|---|
${queue.map((p, i) => `| ${i + 1} | ${cell(p)} | ${p.status} | ${bearsOn(p)} | ${cites(p)} |`).join('\n')}
`;

// Timeline
const years = papers.map((p) => p.year);
const [y0, y1] = [Math.min(...years), Math.max(...years)];
const span = Array.from({ length: y1 - y0 + 1 }, (_, i) => y0 + i);
const count = (y, t) => papers.filter((p) => p.year === y && p.type === t).length || '·';
const timelinePage =
	header('Timeline', 'How many papers there are per year and type, to show where the literature is thin.', 4) +
	`Papers in the [paper overview](/resources/papers/) per year and type. This covers only the papers these notes use, not the whole field, and a dot means none
in the list. Read it as a map of what has been collected so far.

| Year | ${typeOrder.join(' | ')} | Total |
|---|${typeOrder.map(() => '---').join('|')}|---|
${span
	.map((y) => `| ${y} | ${typeOrder.map((t) => count(y, t)).join(' | ')} | ${papers.filter((p) => p.year === y).length || '·'} |`)
	.join('\n')}
| **All** | ${typeOrder.map((t) => `**${papers.filter((p) => p.type === t).length}**`).join(' | ')} | **${papers.length}** |
`;

// BibTeX
const used = new Set();
const key = (p) => {
	const first = p.ref.split(/,| and | et al/)[0].trim().split(/\s+/).at(-1).replace(/[^A-Za-z]/g, '');
	let k = `${first}${p.year}`;
	for (let s = 98; used.has(k); s++) k = `${first}${p.year}${String.fromCharCode(s)}`;
	used.add(k);
	return k;
};
const bib =
	'% Generated by scripts/papers.mjs from data/papers.json. Only what the list knows is given:\n% the full reference is in the note field.\n\n' +
	papers
		.map((p) =>
			[
				`@misc{${key(p)},`,
				p.title ? `  title = {{${p.title}}},` : null,
				`  year = {${p.year}},`,
				p.doi ? `  doi = {${p.doi}},` : null,
				p.arxiv ? `  eprint = {${p.arxiv}},\n  archiveprefix = {arXiv},` : null,
				`  note = {${p.ref}}`,
				'}',
			]
				.filter(Boolean)
				.join('\n'),
		)
		.join('\n\n') +
	'\n';

const outputs = {
	'src/content/docs/resources/papers.md': papersPage,
	'src/content/docs/resources/reading-queue.md': queuePage,
	'src/content/docs/resources/timeline.md': timelinePage,
	'public/papers.bib': bib,
};

if (process.argv.includes('--check')) {
	const stale = Object.entries(outputs).filter(([f, text]) => {
		try {
			return readFileSync(new URL(f, root), 'utf8') !== text;
		} catch {
			return true;
		}
	});
	if (stale.length) {
		console.error(`Out of date: ${stale.map(([f]) => f).join(', ')}\nRun: npm run papers`);
		process.exit(1);
	}
	console.log('paper pages are up to date');
} else {
	for (const [f, text] of Object.entries(outputs)) writeFileSync(new URL(f, root), text);
	console.log(`wrote ${papers.length} papers to ${Object.keys(outputs).length} files`);
}
